# Who is really in the privileged groups? -Recursive expands nested groups.
$groups = 'Domain Admins','Enterprise Admins','Schema Admins','Administrators',
          'Account Operators','Backup Operators','Server Operators','Print Operators'
foreach ($g in $groups) {
    try {
        Get-ADGroupMember -Identity $g -Recursive |
            Select-Object @{n='Group';e={$g}}, SamAccountName, objectClass
    } catch {
        Write-Warning "$g not found here (Enterprise and Schema Admins live in the forest root)"
    }
}

# On a DC: which accounts still authenticate with NTLMv1? (4624 lists the package name)
Get-WinEvent -LogName Security -FilterXPath "*[System[EventID=4624] and EventData[Data[@Name='LmPackageName']='NTLM V1']]" -MaxEvents 200 |
  ForEach-Object {
    $d = @{}; ([xml]$_.ToXml()).Event.EventData.Data | ForEach-Object { $d[$_.Name] = $_.'#text' }
    [pscustomobject]@{ Time = $_.TimeCreated; User = $d.TargetUserName; From = $d.WorkstationName; IP = $d.IpAddress }
  }

# 1. Accounts with Kerberos pre-authentication disabled (DONT_REQ_PREAUTH = 0x400000 = 4194304)
Get-ADUser -LDAPFilter '(userAccountControl:1.2.840.113556.1.4.803:=4194304)' -Properties userAccountControl, pwdLastSet |
  Select-Object SamAccountName, Enabled, @{n='PasswordSet'; e={[datetime]::FromFileTime($_.pwdLastSet)}}

# 2. On a DC: spraying shape in the last 2,000 failed pre-auth events (4771, code 0x18)
Get-WinEvent -LogName Security -FilterXPath "*[System[EventID=4771] and EventData[Data[@Name='Status']='0x18']]" -MaxEvents 2000 |
  ForEach-Object {
    $d = @{}; ([xml]$_.ToXml()).Event.EventData.Data | ForEach-Object { $d[$_.Name] = $_.'#text' }
    [pscustomobject]@{ Source = $d.IpAddress; User = $d.TargetUserName }
  } | Group-Object Source |
  ForEach-Object { [pscustomobject]@{ Source = $_.Name; Failures = $_.Count; DistinctUsers = ($_.Group.User | Sort-Object -Unique).Count } } |
  Sort-Object DistinctUsers -Descending | Select-Object -First 10
